    "id": "egbac_prob_ch2_db_medium_20",
    "titleEn": "Exponential Memoryless Property Conditional Probability #10",
    "titleAr": "الاحتمال الشرطي لخاصية فقدان الذاكرة في التوزيع الأسي رقم 10",
    "difficulty": "medium",
    "questionEn": "Let $X \\sim \\text{Exp}(\\lambda = 11)$ be an exponential random variable. Using the memoryless property, evaluate the conditional probability $P(X > s + 2 \\mid X > s)$ for any $s > 0$.",
    "questionAr": "ليكن $X \\sim \\text{Exp}(\\lambda = 11)$ متغيراً عشوائياً أسياً. باستخدام خاصية فقدان الذاكرة (Memoryless Property)، احسب الاحتمال الشرطي $P(X > s + 2 \\mid X > s)$ لأي $s > 0$.",
    "optionsEn": [
      "$P(X > s + 2 \\mid X > s) = e^{-24}$",
      "$P(X > s + 2 \\mid X > s) = e^{-21}$",
      "$P(X > s + 2 \\mid X > s) = 1 - e^{-22}$",
      "$P(X > s + 2 \\mid X > s) = e^{-22}$"
    ],
    "optionsAr": [
      "$P(X > s + 2 \\mid X > s) = e^{-24}$",
      "$P(X > s + 2 \\mid X > s) = e^{-21}$",
      "$P(X > s + 2 \\mid X > s) = 1 - e^{-22}$",
      "$P(X > s + 2 \\mid X > s) = e^{-22}$"
    ],
    "correctAnswer": "$P(X > s + 2 \\mid X > s) = e^{-22}$",
    "correctIndex": 3,
    "hintEn": "The memoryless property states P(X > s + t | X > s) = P(X > t) = e^(-lambda * t).",
    "hintAr": "تنص خاصية فقدان الذاكرة على أن P(X > s + t | X > s) = P(X > t) = e^(-lambda * t).",
    "stepByStepSolutionEn": [
      "1. By the memoryless property of the exponential distribution: $P(X > s + t \\mid X > s) = P(X > t)$.",
      "2. Here $t = 2$ and $\\lambda = 11$.",
      "3. For an exponential distribution, the survival function is $P(X > t) = e^{-\\lambda t} = e^{-(11)(2)} = e^{-22}$."
    ],
    "stepByStepSolutionAr": [
      "١. بخاصية فقدان الذاكرة للتوزيع الأسي: $P(X > s + t \\mid X > s) = P(X > t)$.",
      "٢. هنا $t = 2$ والمعامل $\\lambda = 11$.",
      "٣. دالة البقاء للتوزيع الأسي هي: $P(X > t) = e^{-\\lambda t} = e^{-(11)(2)} = e^{-22}$."
    ],
    "teacherTipEn": "The exponential distribution is the ONLY continuous distribution with the memoryless property.",
    "teacherTipAr": "التوزيع الأسي هو التوزيع المتصل الوحيد على الإطلاق الذي يتمتع بخاصية فقدان الذاكرة."
