      "$\\hat{\\lambda}_{\\text{MLE}} = \\frac{n}{\\sum_{i=1}^n X_i}$",
      "$\\hat{\\lambda}_{\\text{MLE}} = \\sqrt{\\frac{n}{\\sum_{i=1}^n X_i^2}}$"
