      "٣. المشتقة الأولى: $\\frac{n}{\\lambda} - \\sum_{i=1}^n X_i = 0$.",
      "٤. حل المعادلة يعطي مقدر الإمكان الأكبر: $\\hat{\\lambda}_{\\text{MLE}} = \\frac{n}{\\sum_{i=1}^n X_i} = \\frac{1}{\\bar{X}}$."
