    "questionEn": "Let $X$ be uniformly distributed on $(0, 1)$, with PDF $f_X(x) = 1$ for $0 < x < 1$. Define $Y = -\\frac{1}{4} \\ln X$. Use the Jacobian transformation technique to derive the probability density function $f_Y(y)$ for $y > 0$.",
    "questionAr": "ليكن $X$ متغيراً عشوائياً موزعاً بانتظام على الفترة $(0, 1)$ بدالة كثافة $f_X(x) = 1$. عرّف $Y = -\\frac{1}{4} \\ln X$. استخدم طريقة تحويل اليعقوبي (Jacobian) لإيجاد دالة الكثافة الاحتمالية $f_Y(y)$ لكل $y > 0$.",
    "optionsEn": [
      "$f_Y(y) = 4 e^{-4 y}, \\quad y > 0$",
      "$f_Y(y) = \\frac{1}{4} e^{-4 y}, \\quad y > 0$",
      "$f_Y(y) = 4 e^{-y / 4}, \\quad y > 0$",
      "$f_Y(y) = e^{-4 y}, \\quad y > 0$"
    ],
    "optionsAr": [
      "$f_Y(y) = 4 e^{-4 y}, \\quad y > 0$",
      "$f_Y(y) = \\frac{1}{4} e^{-4 y}, \\quad y > 0$",
      "$f_Y(y) = 4 e^{-y / 4}, \\quad y > 0$",
      "$f_Y(y) = e^{-4 y}, \\quad y > 0$"
    ],
    "correctAnswer": "$f_Y(y) = 4 e^{-4 y}, \\quad y > 0$",
    "correctIndex": 0,
    "hintEn": "Invert y = g(x) to get x = e^(-lambda * y). Then f_Y(y) = f_X(g^-1(y)) * |dx/dy|.",
    "hintAr": "اعكس الدالة للحصول على x = e^(-lambda * y)، ثم طبق f_Y(y) = f_X(x) * |dx/dy|.",
    "stepByStepSolutionEn": [
      "1. Inverse transformation: $y = -\\frac{1}{4} \\ln x \\implies -4 y = \\ln x \\implies x = e^{-4 y}$.",
      "2. Compute the derivative: $\\frac{dx}{dy} = -4 e^{-4 y}$.",
      "3. Absolute Jacobian: $\\left| \\frac{dx}{dy} \\right| = 4 e^{-4 y}$.",
      "4. Density formula: $f_Y(y) = f_X(e^{-4 y}) \\left| \\frac{dx}{dy} \\right| = 1 \\times 4 e^{-4 y} = 4 e^{-4 y}$ for $y > 0$."
    ],
    "stepByStepSolutionAr": [
      "١. الدالة العكسية: $y = -\\frac{1}{4} \\ln x \\implies x = e^{-4 y}$.",
      "٢. المشتقة: $\\frac{dx}{dy} = -4 e^{-4 y}$.",
      "٣. مقياس محدد اليعقوبي: $\\left| \\frac{dx}{dy} \\right| = 4 e^{-4 y}$.",
      "٤. دالة الكثافة: $f_Y(y) = 1 \\times 4 e^{-4 y} = 4 e^{-4 y}$ لكل $y > 0$."
    ],
    "teacherTipEn": "This transformation is the mathematical foundation of the Inverse Transform Sampling algorithm used in Monte Carlo simulations.",
    "teacherTipAr": "هذا التحويل هو الأساس الرياضي لخوارزمية توليد الأعداد العشوائية بالتحويل العكسي المستخدمة في محاكاة مونت كارلو."
