    "difficulty": "hots",
    "questionEn": "Let $X$ be uniformly distributed on $(0, 1)$, with PDF $f_X(x) = 1$ for $0 < x < 1$. Define $Y = -\\frac{1}{11} \\ln X$. Use the Jacobian transformation technique to derive the probability density function $f_Y(y)$ for $y > 0$.",
    "questionAr": "ليكن $X$ متغيراً عشوائياً موزعاً بانتظام على الفترة $(0, 1)$ بدالة كثافة $f_X(x) = 1$. عرّف $Y = -\\frac{1}{11} \\ln X$. استخدم طريقة تحويل اليعقوبي (Jacobian) لإيجاد دالة الكثافة الاحتمالية $f_Y(y)$ لكل $y > 0$.",
